// Preset dimensions are dynamic. Stretch the same inside-border/grey-fill
// vocabulary to the actual aspect ratio, keeping very thin silhouettes valid.
static void drawStyledPresetIcon(ImDrawList* draw,ImVec2 at,float width,float height,ImU32 ink,ImU32 surface,bool clipboard) {
    const auto fg=ImGui::ColorConvertU32ToFloat4(ink),bg=ImGui::ColorConvertU32ToFloat4(surface);
    const float tone=.67431195f;
    const auto fill=ImGui::ColorConvertFloat4ToU32({fg.x+(bg.x-fg.x)*tone,fg.y+(bg.y-fg.y)*tone,fg.z+(bg.z-fg.z)*tone,fg.w});
    const float unit=std::max(width,height)/9;
    const float stroke=std::min(unit,std::min(width,height)*.5f),inset=stroke*.5f;
    draw->AddRectFilled(at,{at.x+width,at.y+height},fill);
    draw->AddRect({at.x+inset,at.y+inset},{at.x+width-inset,at.y+height-inset},ink,0,0,stroke);
    if(clipboard) {
        const float clipWidth=std::min(width,4*unit),clipHeight=2*unit;
        const float clipStroke=std::min(unit,clipWidth*.5f),clipInset=clipStroke*.5f;
        const ImVec2 a={at.x+(width-clipWidth)*.5f,at.y-unit},b={a.x+clipWidth,a.y+clipHeight};
        draw->AddRectFilled(a,b,fill,.5f*unit);
        draw->AddRect({a.x+clipInset,a.y+clipInset},{b.x-clipInset,b.y-clipInset},ink,.5f*unit,0,clipStroke);
    }
}
